#!/usr/bin/env bun

import { readdirSync, statSync } from 'fs';
import { join } from 'path';
import { EnhancedFhirBundleLoader } from '../loaders/enhanced-fhir-loader';

/**
 * Patient Demographics Outlier Detection
 * 
 * Validates patient demographic data for outliers and unusual patterns:
 * - Age distribution and impossible ages
 * - Birth date validation (future dates, historical extremes)
 * - Gender code consistency
 * - Name patterns and character validation
 * - Address and geographic distribution
 * - Identifier format validation
 */

const DATA_DIR = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface DemographicOutlier {
  patientId: string;
  filename: string;
  outlierType: string;
  description: string;
  value: any;
  severity: 'low' | 'medium' | 'high';
}

interface DemographicStats {
  totalPatients: number;
  ageDistribution: Record<string, number>;
  genderDistribution: Record<string, number>;
  birthYearRange: { min: number; max: number };
  namePatterns: {
    averageGivenNameLength: number;
    averageFamilyNameLength: number;
    unusualCharacters: string[];
    maxNameLength: number;
  };
  addressPatterns: {
    states: Record<string, number>;
    countries: Record<string, number>;
    cities: Record<string, number>;
  };
  identifierPatterns: {
    ssnFormats: Record<string, number>;
    phoneFormats: Record<string, number>;
  };
  outliers: DemographicOutlier[];
}

async function main() {
  console.log('🔍 PATIENT DEMOGRAPHICS OUTLIER DETECTION\n');

  const files = readdirSync(DATA_DIR).filter(f => f.endsWith('.json'));

  // Sample files for analysis
  const sampleFiles = files
    .map(f => ({ filename: f, size: statSync(join(DATA_DIR, f)).size }))
    .sort((a, b) => a.size - b.size)
    .filter((_, i, arr) => i % Math.floor(arr.length / 20) === 0) // Sample every 5%
    .slice(0, 20)
    .map(f => f.filename);

  console.log(`📊 Analyzing demographics from ${sampleFiles.length} patient files...\n`);

  const loader = new EnhancedFhirBundleLoader({ strict: false });
  const stats: DemographicStats = {
    totalPatients: 0,
    ageDistribution: {},
    genderDistribution: {},
    birthYearRange: { min: 2100, max: 1800 },
    namePatterns: {
      averageGivenNameLength: 0,
      averageFamilyNameLength: 0,
      unusualCharacters: [],
      maxNameLength: 0
    },
    addressPatterns: {
      states: {},
      countries: {},
      cities: {}
    },
    identifierPatterns: {
      ssnFormats: {},
      phoneFormats: {}
    },
    outliers: []
  };

  for (const filename of sampleFiles) {
    const filePath = join(DATA_DIR, filename);

    try {
      const result = await loader.loadFromFile(filePath);

      if (result.success && result.processedBundle) {
        const patient = result.processedBundle.patient;
        stats.totalPatients++;

        await analyzePatientDemographics(patient, filename, stats);
      }
    } catch (error) {
      console.log(`❌ Error processing ${filename}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // Calculate averages
  if (stats.totalPatients > 0) {
    const totalGivenLength = Object.values(stats.namePatterns).reduce((sum, val) => 
      typeof val === 'number' ? sum + val : sum, 0
    );
    stats.namePatterns.averageGivenNameLength = totalGivenLength / stats.totalPatients;
  }

  // Report findings
  reportDemographicFindings(stats);
}

async function analyzePatientDemographics(patient: any, filename: string, stats: DemographicStats) {
  const outliers = stats.outliers;
  const patientId = patient.id;

  // Age and birth date analysis
  if (patient.birthDate) {
    const birthDate = new Date(patient.birthDate);
    const currentDate = new Date();
    const age = currentDate.getFullYear() - birthDate.getFullYear();
    const birthYear = birthDate.getFullYear();

    // Update birth year range
    stats.birthYearRange.min = Math.min(stats.birthYearRange.min, birthYear);
    stats.birthYearRange.max = Math.max(stats.birthYearRange.max, birthYear);

    // Age distribution
    const ageGroup = `${Math.floor(age / 10) * 10}-${Math.floor(age / 10) * 10 + 9}`;
    stats.ageDistribution[ageGroup] = (stats.ageDistribution[ageGroup] || 0) + 1;

    // Outlier detection
    if (age < 0) {
      outliers.push({
        patientId,
        filename,
        outlierType: 'FUTURE_BIRTH_DATE',
        description: `Birth date ${patient.birthDate} is in the future`,
        value: patient.birthDate,
        severity: 'high'
      });
    }

    if (age > 150) {
      outliers.push({
        patientId,
        filename,
        outlierType: 'EXTREME_AGE',
        description: `Patient age ${age} exceeds 150 years`,
        value: age,
        severity: 'high'
      });
    }

    if (birthYear < 1850) {
      outliers.push({
        patientId,
        filename,
        outlierType: 'HISTORICAL_BIRTH_DATE',
        description: `Birth year ${birthYear} predates reasonable medical records`,
        value: birthYear,
        severity: 'medium'
      });
    }
  }

  // Gender analysis
  if (patient.gender) {
    stats.genderDistribution[patient.gender] = (stats.genderDistribution[patient.gender] || 0) + 1;

    // Check for non-standard gender codes
    const standardGenders = ['male', 'female', 'other', 'unknown'];
    if (!standardGenders.includes(patient.gender)) {
      outliers.push({
        patientId,
        filename,
        outlierType: 'NON_STANDARD_GENDER',
        description: `Gender code '${patient.gender}' is not standard FHIR`,
        value: patient.gender,
        severity: 'medium'
      });
    }
  }

  // Name analysis
  if (patient.name && patient.name[0]) {
    const name = patient.name[0];

    if (name.given && name.given[0]) {
      const givenName = name.given[0];
      const familyName = name.family;

      // Length analysis
      stats.namePatterns.maxNameLength = Math.max(
        stats.namePatterns.maxNameLength,
        givenName.length,
        familyName?.length || 0
      );

      // Unusual character detection
      const namePattern = /^[a-zA-Z\s\-\.'áéíóúñüÁÉÍÓÚÑÜ]+$/;
      if (!namePattern.test(givenName)) {
        const unusualChars = givenName.replace(/[a-zA-Z\s\-\.'áéíóúñüÁÉÍÓÚÑÜ]/g, '');
        stats.namePatterns.unusualCharacters.push(...unusualChars.split(''));

        outliers.push({
          patientId,
          filename,
          outlierType: 'UNUSUAL_NAME_CHARACTERS',
          description: `Given name '${givenName}' contains unusual characters: ${unusualChars}`,
          value: givenName,
          severity: 'low'
        });
      }

      if (familyName && !namePattern.test(familyName)) {
        const unusualChars = familyName.replace(/[a-zA-Z\s\-\.'áéíóúñüÁÉÍÓÚÑÜ]/g, '');
        stats.namePatterns.unusualCharacters.push(...unusualChars.split(''));

        outliers.push({
          patientId,
          filename,
          outlierType: 'UNUSUAL_NAME_CHARACTERS',
          description: `Family name '${familyName}' contains unusual characters: ${unusualChars}`,
          value: familyName,
          severity: 'low'
        });
      }

      // Extremely long names
      if (givenName.length > 50) {
        outliers.push({
          patientId,
          filename,
          outlierType: 'EXTREMELY_LONG_NAME',
          description: `Given name '${givenName}' is ${givenName.length} characters (>50)`,
          value: givenName.length,
          severity: 'medium'
        });
      }
    }
  }

  // Address analysis
  if (patient.address && patient.address[0]) {
    const address = patient.address[0];

    if (address.state) {
      stats.addressPatterns.states[address.state] = (stats.addressPatterns.states[address.state] || 0) + 1;
    }

    if (address.country) {
      stats.addressPatterns.countries[address.country] = (stats.addressPatterns.countries[address.country] || 0) + 1;
    }

    if (address.city) {
      stats.addressPatterns.cities[address.city] = (stats.addressPatterns.cities[address.city] || 0) + 1;
    }

    // Postal code validation
    if (address.postalCode && address.country === 'US') {
      const zipPattern = /^\d{5}(-\d{4})?$/;
      if (!zipPattern.test(address.postalCode)) {
        outliers.push({
          patientId,
          filename,
          outlierType: 'INVALID_POSTAL_CODE',
          description: `US postal code '${address.postalCode}' doesn't match standard format`,
          value: address.postalCode,
          severity: 'medium'
        });
      }
    }
  }

  // Identifier analysis
  if (patient.identifier) {
    for (const identifier of patient.identifier) {
      // SSN validation
      if (identifier.system === 'http://hl7.org/fhir/sid/us-ssn' && identifier.value) {
        const ssnPattern = /^\d{3}-\d{2}-\d{4}$/;
        const format = ssnPattern.test(identifier.value) ? 'standard' : 'non-standard';
        stats.identifierPatterns.ssnFormats[format] = (stats.identifierPatterns.ssnFormats[format] || 0) + 1;

        if (!ssnPattern.test(identifier.value)) {
          outliers.push({
            patientId,
            filename,
            outlierType: 'INVALID_SSN_FORMAT',
            description: `SSN '${identifier.value}' doesn't match XXX-XX-XXXX format`,
            value: identifier.value,
            severity: 'medium'
          });
        }

        // Check for obviously fake SSNs
        if (identifier.value.startsWith('000-') || identifier.value.startsWith('666-') || identifier.value.startsWith('9')) {
          outliers.push({
            patientId,
            filename,
            outlierType: 'SUSPICIOUS_SSN',
            description: `SSN '${identifier.value}' uses invalid area number`,
            value: identifier.value,
            severity: 'low'
          });
        }
      }
    }
  }

  // Phone number analysis
  if (patient.telecom) {
    for (const telecom of patient.telecom) {
      if (telecom.system === 'phone' && telecom.value) {
        const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
        const format = phonePattern.test(telecom.value) ? 'standard' : 'non-standard';
        stats.identifierPatterns.phoneFormats[format] = (stats.identifierPatterns.phoneFormats[format] || 0) + 1;

        if (!phonePattern.test(telecom.value)) {
          outliers.push({
            patientId,
            filename,
            outlierType: 'INVALID_PHONE_FORMAT',
            description: `Phone '${telecom.value}' doesn't match XXX-XXX-XXXX format`,
            value: telecom.value,
            severity: 'low'
          });
        }
      }
    }
  }
}

function reportDemographicFindings(stats: DemographicStats) {
  console.log('📊 DEMOGRAPHIC ANALYSIS RESULTS\n');
  console.log('=' .repeat(50));

  console.log(`Total patients analyzed: ${stats.totalPatients}\n`);

  // Age distribution
  console.log('👥 Age Distribution:');
  Object.entries(stats.ageDistribution)
    .sort(([a], [b]) => parseInt(a) - parseInt(b))
    .forEach(([ageGroup, count]) => {
      console.log(`  ${ageGroup}: ${count}`);
    });
  console.log('');

  // Gender distribution
  console.log('⚧️ Gender Distribution:');
  Object.entries(stats.genderDistribution).forEach(([gender, count]) => {
    console.log(`  ${gender}: ${count}`);
  });
  console.log('');

  // Birth year range
  console.log(`📅 Birth Year Range: ${stats.birthYearRange.min} - ${stats.birthYearRange.max}\n`);

  // Geographic distribution
  console.log('🗺️ Geographic Distribution:');
  console.log('States:', Object.keys(stats.addressPatterns.states).length);
  const topStates = Object.entries(stats.addressPatterns.states)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10);
  topStates.forEach(([state, count]) => {
    console.log(`  ${state}: ${count}`);
  });
  console.log('');

  // Identifier patterns
  console.log('🆔 Identifier Patterns:');
  console.log('SSN Formats:', stats.identifierPatterns.ssnFormats);
  console.log('Phone Formats:', stats.identifierPatterns.phoneFormats);
  console.log('');

  // Outliers by severity
  console.log('🚨 OUTLIERS DETECTED:\n');

  const severityGroups = {
    high: stats.outliers.filter(o => o.severity === 'high'),
    medium: stats.outliers.filter(o => o.severity === 'medium'),
    low: stats.outliers.filter(o => o.severity === 'low')
  };

  console.log(`❗ HIGH Severity: ${severityGroups.high.length}`);
  severityGroups.high.slice(0, 5).forEach(outlier => {
    console.log(`  🔥 ${outlier.outlierType}: ${outlier.description}`);
    console.log(`     File: ${outlier.filename}, Patient: ${outlier.patientId}`);
  });
  console.log('');

  console.log(`⚠️  MEDIUM Severity: ${severityGroups.medium.length}`);
  severityGroups.medium.slice(0, 5).forEach(outlier => {
    console.log(`  ⚠️  ${outlier.outlierType}: ${outlier.description}`);
    console.log(`     File: ${outlier.filename}, Patient: ${outlier.patientId}`);
  });
  console.log('');

  console.log(`ℹ️  LOW Severity: ${severityGroups.low.length}`);
  severityGroups.low.slice(0, 3).forEach(outlier => {
    console.log(`  ℹ️  ${outlier.outlierType}: ${outlier.description}`);
  });

  // Summary statistics
  console.log('\n📈 OUTLIER SUMMARY:');
  const outlierTypes = [...new Set(stats.outliers.map(o => o.outlierType))];
  outlierTypes.forEach(type => {
    const count = stats.outliers.filter(o => o.outlierType === type).length;
    console.log(`  ${type}: ${count}`);
  });

  console.log('\n✅ Patient demographics analysis complete!');
}

if (import.meta.main) {
  main().catch(console.error);
}

#!/usr/bin/env bun

import { readdirSync, statSync } from 'fs';
import { join } from 'path';
import { EnhancedFhirBundleLoader } from '../loaders/enhanced-fhir-loader';

/**
 * Clinical Observations Outlier Detection
 * 
 * Validates clinical observation data for outliers and unusual patterns:
 * - Vital signs ranges (blood pressure, heart rate, temperature, etc.)
 * - Lab result distributions and extreme values
 * - Observation units and value types
 * - Temporal patterns and frequencies
 * - Missing or inconsistent data
 */

const DATA_DIR = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface ObservationOutlier {
  patientId: string;
  filename: string;
  observationId: string;
  observationType: string;
  outlierType: string;
  description: string;
  value: any;
  unit?: string;
  date?: string;
  severity: 'low' | 'medium' | 'high';
}

interface ClinicalRanges {
  [key: string]: {
    min: number;
    max: number;
    expectedUnit?: string;
    description: string;
  };
}

// Clinical normal ranges for outlier detection
const CLINICAL_RANGES: ClinicalRanges = {
  // Vital Signs
  'systolic_bp': { min: 60, max: 250, expectedUnit: 'mmHg', description: 'Systolic Blood Pressure' },
  'diastolic_bp': { min: 30, max: 150, expectedUnit: 'mmHg', description: 'Diastolic Blood Pressure' },
  'heart_rate': { min: 20, max: 250, expectedUnit: '/min', description: 'Heart Rate' },
  'respiratory_rate': { min: 5, max: 60, expectedUnit: '/min', description: 'Respiratory Rate' },
  'body_temperature': { min: 32, max: 45, expectedUnit: 'Cel', description: 'Body Temperature (Celsius)' },
  'body_weight': { min: 0.5, max: 500, expectedUnit: 'kg', description: 'Body Weight' },
  'body_height': { min: 20, max: 250, expectedUnit: 'cm', description: 'Body Height' },
  'bmi': { min: 10, max: 80, expectedUnit: 'kg/m2', description: 'Body Mass Index' },

  // Lab Values
  'glucose': { min: 20, max: 800, expectedUnit: 'mg/dL', description: 'Blood Glucose' },
  'cholesterol': { min: 50, max: 500, expectedUnit: 'mg/dL', description: 'Total Cholesterol' },
  'hemoglobin': { min: 4, max: 20, expectedUnit: 'g/dL', description: 'Hemoglobin' },
  'creatinine': { min: 0.3, max: 15, expectedUnit: 'mg/dL', description: 'Serum Creatinine' },
  'sodium': { min: 120, max: 160, expectedUnit: 'mEq/L', description: 'Serum Sodium' },
  'potassium': { min: 2.5, max: 7, expectedUnit: 'mEq/L', description: 'Serum Potassium' },

  // Other
  'oxygen_saturation': { min: 60, max: 100, expectedUnit: '%', description: 'Oxygen Saturation' },
  'pain_score': { min: 0, max: 10, expectedUnit: '{score}', description: 'Pain Score 0-10' }
};

interface ClinicalStats {
  totalObservations: number;
  observationTypes: Record<string, number>;
  valueTypeDistribution: Record<string, number>;
  unitDistribution: Record<string, number>;
  dateRangeIssues: number;
  outliers: ObservationOutlier[];
  clinicalRangeViolations: Record<string, { count: number; examples: any[] }>;
}

async function main() {
  console.log('🔬 CLINICAL OBSERVATIONS OUTLIER DETECTION\n');

  const files = readdirSync(DATA_DIR).filter(f => f.endsWith('.json'));

  // Sample files for analysis - focus on medium to large files for more observations
  const sampleFiles = files
    .map(f => ({ filename: f, size: statSync(join(DATA_DIR, f)).size }))
    .filter(f => f.size > 5 * 1024 * 1024) // > 5MB
    .sort((a, b) => a.size - b.size)
    .filter((_, i, arr) => i % Math.floor(arr.length / 10) === 0) // Sample every 10%
    .slice(0, 10)
    .map(f => f.filename);

  console.log(`📊 Analyzing clinical observations from ${sampleFiles.length} patient files...\n`);

  const loader = new EnhancedFhirBundleLoader({ strict: false });
  const stats: ClinicalStats = {
    totalObservations: 0,
    observationTypes: {},
    valueTypeDistribution: {},
    unitDistribution: {},
    dateRangeIssues: 0,
    outliers: [],
    clinicalRangeViolations: {}
  };

  for (const filename of sampleFiles) {
    const filePath = join(DATA_DIR, filename);

    try {
      const result = await loader.loadFromFile(filePath);

      if (result.success && result.processedBundle) {
        const observations = result.processedBundle.observations;
        const patientId = result.processedBundle.patient.id;
        const patientBirthDate = result.processedBundle.patient.birthDate;

        console.log(`📋 ${filename}: ${observations.length} observations`);

        for (const observation of observations) {
          await analyzeObservation(observation, patientId, patientBirthDate, filename, stats);
        }
      }
    } catch (error) {
      console.log(`❌ Error processing ${filename}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // Report findings
  reportClinicalFindings(stats);
}

async function analyzeObservation(observation: any, patientId: string, patientBirthDate: string, filename: string, stats: ClinicalStats) {
  stats.totalObservations++;
  const outliers = stats.outliers;

  // Get observation details
  const observationType = observation.code?.coding?.[0]?.display || 'Unknown';
  const observationId = observation.id;
  const effectiveDate = observation.effectiveDateTime;

  // Count observation types
  stats.observationTypes[observationType] = (stats.observationTypes[observationType] || 0) + 1;

  // Analyze value types
  let valueType = 'none';
  let value: any = null;
  let unit: string | undefined;

  if (observation.valueQuantity) {
    valueType = 'quantity';
    value = observation.valueQuantity.value;
    unit = observation.valueQuantity.unit || observation.valueQuantity.code;
  } else if (observation.valueCodeableConcept) {
    valueType = 'codeable';
    value = observation.valueCodeableConcept.coding?.[0]?.display;
  } else if (observation.valueString) {
    valueType = 'string';
    value = observation.valueString;
  } else if (observation.valueBoolean !== undefined) {
    valueType = 'boolean';
    value = observation.valueBoolean;
  } else if (observation.component && observation.component.length > 0) {
    valueType = 'component';
    // Analyze components separately
    for (const component of observation.component) {
      if (component.valueQuantity) {
        await analyzeObservationValue(
          component.code?.coding?.[0]?.display || 'Component',
          component.valueQuantity.value,
          component.valueQuantity.unit || component.valueQuantity.code,
          patientId, observationId, observationType, effectiveDate, filename, outliers
        );
      }
    }
  }

  stats.valueTypeDistribution[valueType] = (stats.valueTypeDistribution[valueType] || 0) + 1;

  if (unit) {
    stats.unitDistribution[unit] = (stats.unitDistribution[unit] || 0) + 1;
  }

  // Analyze quantity values for clinical ranges
  if (valueType === 'quantity' && typeof value === 'number') {
    await analyzeObservationValue(observationType, value, unit, patientId, observationId, observationType, effectiveDate, filename, outliers);
  }

  // Date validation
  if (effectiveDate) {
    const obsDate = new Date(effectiveDate);
    const currentDate = new Date();
    const birthDate = new Date(patientBirthDate);

    // Future observation dates
    if (obsDate > currentDate) {
      outliers.push({
        patientId,
        filename,
        observationId,
        observationType,
        outlierType: 'FUTURE_OBSERVATION_DATE',
        description: `Observation date ${effectiveDate} is in the future`,
        value: effectiveDate,
        date: effectiveDate,
        severity: 'high'
      });
    }

    // Observation before birth
    if (obsDate < birthDate) {
      outliers.push({
        patientId,
        filename,
        observationId,
        observationType,
        outlierType: 'OBSERVATION_BEFORE_BIRTH',
        description: `Observation date ${effectiveDate} is before patient birth date ${patientBirthDate}`,
        value: effectiveDate,
        date: effectiveDate,
        severity: 'high'
      });
    }
  }

  // Missing value detection
  if (valueType === 'none' && (!observation.component || observation.component.length === 0)) {
    outliers.push({
      patientId,
      filename,
      observationId,
      observationType,
      outlierType: 'MISSING_OBSERVATION_VALUE',
      description: `Observation has no value (quantity, codeable, string, boolean, or components)`,
      value: null,
      date: effectiveDate,
      severity: 'medium'
    });
  }
}

async function analyzeObservationValue(
  observationType: string, 
  value: number, 
  unit: string | undefined, 
  patientId: string, 
  observationId: string, 
  fullType: string,
  effectiveDate: string | undefined, 
  filename: string, 
  outliers: ObservationOutlier[]
) {
  // Normalize observation type for range checking
  const normalizedType = normalizeObservationType(observationType);
  const clinicalRange = CLINICAL_RANGES[normalizedType];

  if (clinicalRange) {
    // Check value range
    if (value < clinicalRange.min || value > clinicalRange.max) {
      outliers.push({
        patientId,
        filename,
        observationId,
        observationType: fullType,
        outlierType: 'CLINICAL_RANGE_VIOLATION',
        description: `${observationType} value ${value} ${unit || ''} outside normal range ${clinicalRange.min}-${clinicalRange.max}`,
        value,
        unit,
        date: effectiveDate,
        severity: value < clinicalRange.min * 0.5 || value > clinicalRange.max * 2 ? 'high' : 'medium'
      });
    }

    // Check unit consistency
    if (clinicalRange.expectedUnit && unit && unit !== clinicalRange.expectedUnit) {
      outliers.push({
        patientId,
        filename,
        observationId,
        observationType: fullType,
        outlierType: 'UNEXPECTED_UNIT',
        description: `${observationType} has unit '${unit}', expected '${clinicalRange.expectedUnit}'`,
        value,
        unit,
        date: effectiveDate,
        severity: 'low'
      });
    }
  }

  // Extreme value detection (regardless of known ranges)
  if (value < 0 && !['body_temperature'].includes(normalizedType)) {
    outliers.push({
      patientId,
      filename,
      observationId,
      observationType: fullType,
      outlierType: 'NEGATIVE_VALUE',
      description: `${observationType} has negative value ${value} which is unusual`,
      value,
      unit,
      date: effectiveDate,
      severity: 'medium'
    });
  }

  // Extremely large values
  if (value > 10000) {
    outliers.push({
      patientId,
      filename,
      observationId,
      observationType: fullType,
      outlierType: 'EXTREMELY_LARGE_VALUE',
      description: `${observationType} has extremely large value ${value}`,
      value,
      unit,
      date: effectiveDate,
      severity: 'medium'
    });
  }
}

function normalizeObservationType(observationType: string): string {
  const type = observationType.toLowerCase();

  // Map observation names to our clinical range keys
  if (type.includes('systolic') || type.includes('sbp')) return 'systolic_bp';
  if (type.includes('diastolic') || type.includes('dbp')) return 'diastolic_bp';
  if (type.includes('heart rate') || type.includes('pulse')) return 'heart_rate';
  if (type.includes('respiratory rate') || type.includes('breathing')) return 'respiratory_rate';
  if (type.includes('temperature') || type.includes('temp')) return 'body_temperature';
  if (type.includes('weight') && !type.includes('birth')) return 'body_weight';
  if (type.includes('height') && !type.includes('birth')) return 'body_height';
  if (type.includes('bmi') || type.includes('body mass')) return 'bmi';
  if (type.includes('glucose') || type.includes('sugar')) return 'glucose';
  if (type.includes('cholesterol')) return 'cholesterol';
  if (type.includes('hemoglobin') || type.includes('hgb')) return 'hemoglobin';
  if (type.includes('creatinine')) return 'creatinine';
  if (type.includes('sodium')) return 'sodium';
  if (type.includes('potassium')) return 'potassium';
  if (type.includes('oxygen') && type.includes('saturation')) return 'oxygen_saturation';
  if (type.includes('pain') && type.includes('score')) return 'pain_score';

  return 'unknown';
}

