#!/usr/bin/env bun

import { readdirSync, statSync } from 'fs';
import { join } from 'path';
import { EnhancedFhirBundleLoader } from '../loaders/enhanced-fhir-loader';

/**
 * Temporal Patterns Outlier Detection
 * 
 * Validates temporal data for outliers and inconsistencies:
 * - Chronological ordering of events
 * - Condition onset dates vs patient age
 * - Procedure dates and logical sequencing
 * - Encounter durations and frequencies
 * - Time zone consistency
 * - Future dates in records
 * - Birth dates vs medical events
 */

const DATA_DIR = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface TemporalOutlier {
  patientId: string;
  filename: string;
  resourceType: string;
  resourceId: string;
  outlierType: string;
  description: string;
  value: any;
  severity: 'low' | 'medium' | 'high';
}

interface PatientTimeline {
  patientId: string;
  birthDate: string;
  events: Array<{
    date: string;
    type: string;
    resourceType: string;
    resourceId: string;
    description: string;
  }>;
}

interface TemporalStats {
  totalPatients: number;
  totalEvents: number;
  timezoneCounts: Record<string, number>;
  encounterDurations: number[];
  conditionOnsetAges: number[];
  dateRangeSpans: number[];
  outliers: TemporalOutlier[];
  chronologyViolations: number;
  futureEventCount: number;
  impossibleAgeEvents: number;
}

async function main() {
  console.log('⏰ TEMPORAL PATTERNS OUTLIER DETECTION\n');

  const files = readdirSync(DATA_DIR).filter(f => f.endsWith('.json'));

  // Sample files for analysis
  const sampleFiles = files
    .map(f => ({ filename: f, size: statSync(join(DATA_DIR, f)).size }))
    .sort((a, b) => a.size - b.size)
    .filter((_, i, arr) => i % Math.floor(arr.length / 15) === 0) // Sample every ~7%
    .slice(0, 15)
    .map(f => f.filename);

  console.log(`📊 Analyzing temporal patterns from ${sampleFiles.length} patient files...\n`);

  const loader = new EnhancedFhirBundleLoader({ strict: false });
  const stats: TemporalStats = {
    totalPatients: 0,
    totalEvents: 0,
    timezoneCounts: {},
    encounterDurations: [],
    conditionOnsetAges: [],
    dateRangeSpans: [],
    outliers: [],
    chronologyViolations: 0,
    futureEventCount: 0,
    impossibleAgeEvents: 0
  };

  for (const filename of sampleFiles) {
    const filePath = join(DATA_DIR, filename);

    try {
      const result = await loader.loadFromFile(filePath);

      if (result.success && result.processedBundle) {
        console.log(`📋 ${filename}: Analyzing temporal patterns...`);

        const timeline = await buildPatientTimeline(result.processedBundle, filename, stats);
        await analyzeTemporalPatterns(timeline, filename, stats);

        stats.totalPatients++;
      }
    } catch (error) {
      console.log(`❌ Error processing ${filename}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // Report findings
  reportTemporalFindings(stats);
}

async function buildPatientTimeline(processedBundle: any, filename: string, stats: TemporalStats): Promise<PatientTimeline> {
  const { patient, observations, conditions, procedures, encounters } = processedBundle;

  const timeline: PatientTimeline = {
    patientId: patient.id,
    birthDate: patient.birthDate,
    events: []
  };

  // Add observations to timeline
  for (const observation of observations) {
    if (observation.effectiveDateTime) {
      timeline.events.push({
        date: observation.effectiveDateTime,
        type: 'observation',
        resourceType: 'Observation',
        resourceId: observation.id,
        description: observation.code?.coding?.[0]?.display || 'Unknown observation'
      });
    }
  }

  // Add conditions to timeline
  for (const condition of conditions) {
    if (condition.onsetDateTime) {
      timeline.events.push({
        date: condition.onsetDateTime,
        type: 'condition_onset',
        resourceType: 'Condition',
        resourceId: condition.id,
        description: condition.code?.coding?.[0]?.display || 'Unknown condition'
      });
    }

    if (condition.abatementDateTime) {
      timeline.events.push({
        date: condition.abatementDateTime,
        type: 'condition_resolved',
        resourceType: 'Condition',
        resourceId: condition.id,
        description: `Resolved: ${condition.code?.coding?.[0]?.display || 'Unknown condition'}`
      });
    }
  }

  // Add procedures to timeline
  for (const procedure of procedures) {
    if (procedure.performedPeriod?.start) {
      timeline.events.push({
        date: procedure.performedPeriod.start,
        type: 'procedure_start',
        resourceType: 'Procedure',
        resourceId: procedure.id,
        description: procedure.code?.coding?.[0]?.display || 'Unknown procedure'
      });
    }

    if (procedure.performedPeriod?.end) {
      timeline.events.push({
        date: procedure.performedPeriod.end,
        type: 'procedure_end',
        resourceType: 'Procedure',
        resourceId: procedure.id,
        description: `End: ${procedure.code?.coding?.[0]?.display || 'Unknown procedure'}`
      });
    }
  }

  // Add encounters to timeline
  for (const encounter of encounters) {
    if (encounter.period?.start) {
      timeline.events.push({
        date: encounter.period.start,
        type: 'encounter_start',
        resourceType: 'Encounter',
        resourceId: encounter.id,
        description: encounter.type?.[0]?.coding?.[0]?.display || 'Unknown encounter'
      });
    }

    if (encounter.period?.end) {
      timeline.events.push({
        date: encounter.period.end,
        type: 'encounter_end',
        resourceType: 'Encounter',
        resourceId: encounter.id,
        description: `End: ${encounter.type?.[0]?.coding?.[0]?.display || 'Unknown encounter'}`
      });
    }

    // Analyze encounter duration
    if (encounter.period?.start && encounter.period?.end) {
      const startDate = new Date(encounter.period.start);
      const endDate = new Date(encounter.period.end);
      const durationHours = (endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60);
      stats.encounterDurations.push(durationHours);
    }
  }

  // Sort events chronologically
  timeline.events.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  stats.totalEvents += timeline.events.length;

  return timeline;
}

async function analyzeTemporalPatterns(timeline: PatientTimeline, filename: string, stats: TemporalStats) {
  const outliers = stats.outliers;
  const birthDate = new Date(timeline.birthDate);
  const currentDate = new Date();
  const patientId = timeline.patientId;

  // Analyze timezone patterns
  for (const event of timeline.events) {
    const timezoneMatch = event.date.match(/([+-]\d{2}:\d{2})$/);
    if (timezoneMatch) {
      const timezone = timezoneMatch[1];
      stats.timezoneCounts[timezone] = (stats.timezoneCounts[timezone] || 0) + 1;
    }
  }

  // Check for events before birth
  for (const event of timeline.events) {
    const eventDate = new Date(event.date);

    if (eventDate < birthDate) {
      outliers.push({
        patientId,
        filename,
        resourceType: event.resourceType,
        resourceId: event.resourceId,
        outlierType: 'EVENT_BEFORE_BIRTH',
        description: `${event.type} on ${event.date} occurs before birth date ${timeline.birthDate}`,
        value: { eventDate: event.date, birthDate: timeline.birthDate },
        severity: 'high'
      });
      stats.impossibleAgeEvents++;
    }

    // Check for future events
    if (eventDate > currentDate) {
      outliers.push({
        patientId,
        filename,
        resourceType: event.resourceType,
        resourceId: event.resourceId,
        outlierType: 'FUTURE_EVENT',
        description: `${event.type} scheduled for future date ${event.date}`,
        value: event.date,
        severity: 'medium'
      });
      stats.futureEventCount++;
    }
  }

  // Analyze condition onset ages
  for (const event of timeline.events) {
    if (event.type === 'condition_onset') {
      const eventDate = new Date(event.date);
      const ageAtOnset = eventDate.getFullYear() - birthDate.getFullYear();
      stats.conditionOnsetAges.push(ageAtOnset);

      // Check for pediatric conditions in adults
      const pediatricConditions = [
        'birth', 'neonatal', 'congenital', 'childhood', 'infant', 'newborn'
      ];

      if (ageAtOnset > 18 && pediatricConditions.some(keyword => 
        event.description.toLowerCase().includes(keyword)
      )) {
        outliers.push({
          patientId,
          filename,
          resourceType: event.resourceType,
          resourceId: event.resourceId,
          outlierType: 'PEDIATRIC_CONDITION_IN_ADULT',
          description: `Pediatric condition '${event.description}' onset at age ${ageAtOnset}`,
          value: { age: ageAtOnset, condition: event.description },
          severity: 'medium'
        });
      }

      // Check for extremely early onset of age-related conditions
      const ageRelatedConditions = [
        'alzheimer', 'dementia', 'osteoporosis', 'prostate', 'menopause'
      ];

      if (ageAtOnset < 40 && ageRelatedConditions.some(keyword => 
        event.description.toLowerCase().includes(keyword)
      )) {
        outliers.push({
          patientId,
          filename,
          resourceType: event.resourceType,
          resourceId: event.resourceId,
          outlierType: 'EARLY_ONSET_AGE_RELATED_CONDITION',
          description: `Age-related condition '${event.description}' onset at age ${ageAtOnset}`,
          value: { age: ageAtOnset, condition: event.description },
          severity: 'medium'
        });
      }
    }
  }

  // Check chronological consistency
  await checkChronologicalConsistency(timeline, filename, stats);

  // Calculate date range span
  if (timeline.events.length > 0) {
    const firstEvent = new Date(timeline.events[0].date);
    const lastEvent = new Date(timeline.events[timeline.events.length - 1].date);
    const spanYears = (lastEvent.getTime() - firstEvent.getTime()) / (1000 * 60 * 60 * 24 * 365.25);
    stats.dateRangeSpans.push(spanYears);
  }

  // Check for impossible rapid sequences
  await checkRapidSequences(timeline, filename, stats);
}

async function checkChronologicalConsistency(timeline: PatientTimeline, filename: string, stats: TemporalStats) {
  const outliers = stats.outliers;

  // Check for condition resolution before onset
  const conditionEvents = timeline.events.filter(e => 
    e.type === 'condition_onset' || e.type === 'condition_resolved'
  );

  const conditionPairs: Record<string, { onset?: any; resolved?: any }> = {};

  for (const event of conditionEvents) {
    if (!conditionPairs[event.resourceId]) {
      conditionPairs[event.resourceId] = {};
    }

    if (event.type === 'condition_onset') {
      conditionPairs[event.resourceId].onset = event;
    } else if (event.type === 'condition_resolved') {
      conditionPairs[event.resourceId].resolved = event;
    }
  }

  for (const [resourceId, pair] of Object.entries(conditionPairs)) {
    if (pair.onset && pair.resolved) {
      const onsetDate = new Date(pair.onset.date);
      const resolvedDate = new Date(pair.resolved.date);

      if (resolvedDate < onsetDate) {
        outliers.push({
          patientId: timeline.patientId,
          filename,
          resourceType: 'Condition',
          resourceId,
          outlierType: 'CONDITION_RESOLVED_BEFORE_ONSET',
          description: `Condition resolved ${pair.resolved.date} before onset ${pair.onset.date}`,
          value: { onsetDate: pair.onset.date, resolvedDate: pair.resolved.date },
          severity: 'high'
        });
        stats.chronologyViolations++;
      }
    }
  }

  // Check for procedure end before start
  const procedureEvents = timeline.events.filter(e => 
    e.type === 'procedure_start' || e.type === 'procedure_end'
  );

  const procedurePairs: Record<string, { start?: any; end?: any }> = {};

  for (const event of procedureEvents) {
    if (!procedurePairs[event.resourceId]) {
      procedurePairs[event.resourceId] = {};
    }

    if (event.type === 'procedure_start') {
      procedurePairs[event.resourceId].start = event;
    } else if (event.type === 'procedure_end') {
      procedurePairs[event.resourceId].end = event;
    }
  }

  for (const [resourceId, pair] of Object.entries(procedurePairs)) {
    if (pair.start && pair.end) {
      const startDate = new Date(pair.start.date);
      const endDate = new Date(pair.end.date);

      if (endDate < startDate) {
        outliers.push({
          patientId: timeline.patientId,
          filename,
          resourceType: 'Procedure',
          resourceId,
          outlierType: 'PROCEDURE_END_BEFORE_START',
          description: `Procedure ended ${pair.end.date} before start ${pair.start.date}`,
          value: { startDate: pair.start.date, endDate: pair.end.date },
          severity: 'high'
        });
        stats.chronologyViolations++;
      }
    }
  }
}

async function checkRapidSequences(timeline: PatientTimeline, filename: string, stats: TemporalStats) {
  const outliers = stats.outliers;

  // Check for unrealistic rapid procedure sequences
  const procedureStarts = timeline.events.filter(e => e.type === 'procedure_start');

  for (let i = 1; i < procedureStarts.length; i++) {
    const prev = new Date(procedureStarts[i-1].date);
    const curr = new Date(procedureStarts[i].date);
    const minutesBetween = (curr.getTime() - prev.getTime()) / (1000 * 60);

    // Same-day procedures might be suspicious
    if (minutesBetween < 60 && minutesBetween > 0) { // Less than 1 hour apart
      outliers.push({
        patientId: timeline.patientId,
        filename,
        resourceType: 'Procedure',
        resourceId: procedureStarts[i].resourceId,
        outlierType: 'RAPID_PROCEDURE_SEQUENCE',
        description: `Procedures ${minutesBetween.toFixed(0)} minutes apart: '${procedureStarts[i-1].description}' and '${procedureStarts[i].description}'`,
        value: { minutesBetween, procedures: [procedureStarts[i-1].description, procedureStarts[i].description] },
        severity: 'low'
      });
    }
  }

  // Check for unrealistic observation frequencies
  const observations = timeline.events.filter(e => e.type === 'observation');
  const observationsByType: Record<string, any[]> = {};

  for (const obs of observations) {
    if (!observationsByType[obs.description]) {
      observationsByType[obs.description] = [];
    }
    observationsByType[obs.description].push(obs);
  }

  for (const [obsType, obsEvents] of Object.entries(observationsByType)) {
    if (obsEvents.length > 1) {
      // Sort by date
      obsEvents.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

      for (let i = 1; i < obsEvents.length; i++) {
        const prev = new Date(obsEvents[i-1].date);
        const curr = new Date(obsEvents[i].date);
        const minutesBetween = (curr.getTime() - prev.getTime()) / (1000 * 60);

        // Multiple observations of same type within minutes
        if (minutesBetween < 5 && minutesBetween > 0) {
          outliers.push({
            patientId: timeline.patientId,
            filename,
            resourceType: 'Observation',
            resourceId: obsEvents[i].resourceId,
            outlierType: 'RAPID_OBSERVATION_SEQUENCE',
            description: `Same observation type '${obsType}' ${minutesBetween.toFixed(1)} minutes apart`,
            value: { minutesBetween, observationType: obsType },
            severity: 'low'
          });
        }
      }
    }
  }
}

function reportTemporalFindings(stats: TemporalStats) {
  console.log('\n⏰ TEMPORAL PATTERNS ANALYSIS RESULTS\n');
  console.log('=' .repeat(60));

  console.log(`Total patients analyzed: ${stats.totalPatients}`);
