    resourceCounts: {},
    referenceCounts: {},
    brokenReferences: 0,
    codingSystemUsage: {},
    statusCodeUsage: {},
    extensionUsage: {},
    metaProfileUsage: {},
    identifierSystemUsage: {},
    bundleTransactionIntegrity: {
      totalEntries: 0,
      entriesWithRequest: 0,
      entriesWithFullUrl: 0,
      uuidMismatches: 0
    },
    outliers: []
  };

  for (const filename of sampleFiles) {
    const filePath = join(DATA_DIR, filename);

    try {
      const result = await loader.loadFromFile(filePath);

      if (result.success && result.processedBundle) {
        console.log(`📋 ${filename}: Analyzing FHIR structure...`);

        await analyzeBundle(result.processedBundle.bundle, filename, stats);
        await analyzeResources(result.processedBundle, filename, stats);

        stats.totalBundles++;
      }
    } catch (error) {
      console.log(`❌ Error processing ${filename}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // Report findings
  reportStructuralFindings(stats);
}

async function analyzeBundle(bundle: any, filename: string, stats: StructuralStats) {
  const outliers = stats.outliers;

  // Bundle-level validation
  if (bundle.type !== 'transaction') {
    outliers.push({
      patientId: 'bundle',
      filename,
      resourceType: 'Bundle',
      resourceId: bundle.id || 'unknown',
      outlierType: 'UNEXPECTED_BUNDLE_TYPE',
      description: `Bundle type is '${bundle.type}', expected 'transaction'`,
      value: bundle.type,
      severity: 'medium'
    });
  }

  // Analyze bundle entries
  if (bundle.entry) {
    for (const entry of bundle.entry) {
      stats.bundleTransactionIntegrity.totalEntries++;

      // Check for request in transaction bundle
      if (entry.request) {
        stats.bundleTransactionIntegrity.entriesWithRequest++;
      } else {
        outliers.push({
          patientId: entry.resource?.id || 'unknown',
          filename,
          resourceType: entry.resource?.resourceType || 'Unknown',
          resourceId: entry.resource?.id || 'unknown',
          outlierType: 'MISSING_TRANSACTION_REQUEST',
          description: `Bundle entry missing request in transaction bundle`,
          value: null,
          severity: 'medium'
        });
      }

      // Check for fullUrl
      if (entry.fullUrl) {
        stats.bundleTransactionIntegrity.entriesWithFullUrl++;

        // Check UUID consistency
        if (entry.fullUrl.startsWith('urn:uuid:') && entry.resource?.id) {
          const uuidFromUrl = entry.fullUrl.replace('urn:uuid:', '');
          if (uuidFromUrl !== entry.resource.id) {
            stats.bundleTransactionIntegrity.uuidMismatches++;
            outliers.push({
              patientId: entry.resource.id,
              filename,
              resourceType: entry.resource.resourceType,
              resourceId: entry.resource.id,
              outlierType: 'UUID_MISMATCH',
              description: `fullUrl UUID '${uuidFromUrl}' doesn't match resource.id '${entry.resource.id}'`,
              value: { fullUrl: entry.fullUrl, resourceId: entry.resource.id },
              severity: 'high'
            });
          }
        }
      } else {
        outliers.push({
          patientId: entry.resource?.id || 'unknown',
          filename,
          resourceType: entry.resource?.resourceType || 'Unknown',
          resourceId: entry.resource?.id || 'unknown',
          outlierType: 'MISSING_FULL_URL',
          description: `Bundle entry missing fullUrl`,
          value: null,
          severity: 'medium'
        });
      }
    }
  }
}

async function analyzeResources(processedBundle: any, filename: string, stats: StructuralStats) {
  const { bundle, patient, observations, conditions, procedures, encounters } = processedBundle;
  const outliers = stats.outliers;

  // Collect all resources for analysis
  const allResources = [
    patient,
    ...observations,
    ...conditions,
    ...procedures,
    ...encounters
  ];

  // Build resource ID index for reference validation
  const resourceIds = new Set(allResources.map(r => r.id));
  const resourceByUuid: Record<string, any> = {};

  for (const resource of allResources) {
    if (resource.id) {
      resourceByUuid[resource.id] = resource;
    }
  }

  stats.totalResources += allResources.length;

  for (const resource of allResources) {
    await analyzeResourceStructure(resource, filename, stats, resourceIds);
  }

  // Additional reference validation
  await validateResourceReferences(allResources, filename, stats, resourceIds);
}

async function analyzeResourceStructure(resource: any, filename: string, stats: StructuralStats, resourceIds: Set<string>) {
  const outliers = stats.outliers;
  const resourceType = resource.resourceType;
  const resourceId = resource.id;

  // Count resource types
  stats.resourceCounts[resourceType] = (stats.resourceCounts[resourceType] || 0) + 1;

  // Validate resource ID format
  if (resourceId) {
    const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
    if (!uuidPattern.test(resourceId)) {
      outliers.push({
        patientId: resourceId,
        filename,
        resourceType,
        resourceId,
        outlierType: 'INVALID_RESOURCE_ID_FORMAT',
        description: `Resource ID '${resourceId}' is not a valid UUID`,
        value: resourceId,
        severity: 'medium'
      });
    }
  } else {
    outliers.push({
      patientId: 'unknown',
      filename,
      resourceType,
      resourceId: 'missing',
      outlierType: 'MISSING_RESOURCE_ID',
      description: `${resourceType} resource missing required ID`,
      value: null,
      severity: 'high'
    });
  }

  // Analyze meta information
  if (resource.meta) {
    if (resource.meta.profile) {
      for (const profile of resource.meta.profile) {
        stats.metaProfileUsage[profile] = (stats.metaProfileUsage[profile] || 0) + 1;
      }
    }
  }

  // Analyze extensions
  if (resource.extension) {
    for (const extension of resource.extension) {
      if (extension.url) {
        stats.extensionUsage[extension.url] = (stats.extensionUsage[extension.url] || 0) + 1;
      }
    }
  }

  // Analyze identifiers
  if (resource.identifier) {
    for (const identifier of resource.identifier) {
      if (identifier.system) {
        stats.identifierSystemUsage[identifier.system] = (stats.identifierSystemUsage[identifier.system] || 0) + 1;
      }
    }
  }

  // Resource-specific validation
  await analyzeResourceSpecificStructure(resource, filename, stats);
}

async function analyzeResourceSpecificStructure(resource: any, filename: string, stats: StructuralStats) {
  const outliers = stats.outliers;
  const resourceType = resource.resourceType;
  const resourceId = resource.id;

  // Observation-specific validation
  if (resourceType === 'Observation') {
    // Status validation
    if (resource.status) {
      const key = `Observation.status.${resource.status}`;
      stats.statusCodeUsage[key] = (stats.statusCodeUsage[key] || 0) + 1;

      const validStatuses = ['registered', 'preliminary', 'final', 'amended', 'corrected', 'cancelled', 'entered-in-error', 'unknown'];
      if (!validStatuses.includes(resource.status)) {
        outliers.push({
          patientId: resourceId,
          filename,
          resourceType,
          resourceId,
          outlierType: 'INVALID_OBSERVATION_STATUS',
          description: `Observation status '${resource.status}' is not a valid FHIR status`,
          value: resource.status,
          severity: 'medium'
        });
      }
    }

    // Coding system validation
    if (resource.code?.coding) {
      for (const coding of resource.code.coding) {
        if (coding.system) {
          stats.codingSystemUsage[coding.system] = (stats.codingSystemUsage[coding.system] || 0) + 1;
        }
      }
    }
  }

  // Condition-specific validation
  if (resourceType === 'Condition') {
    // Clinical status validation
    if (resource.clinicalStatus?.coding) {
      for (const coding of resource.clinicalStatus.coding) {
        if (coding.code) {
          const key = `Condition.clinicalStatus.${coding.code}`;
          stats.statusCodeUsage[key] = (stats.statusCodeUsage[key] || 0) + 1;
        }
      }
    }

    // Verification status validation
    if (resource.verificationStatus?.coding) {
      for (const coding of resource.verificationStatus.coding) {
        if (coding.code) {
          const key = `Condition.verificationStatus.${coding.code}`;
          stats.statusCodeUsage[key] = (stats.statusCodeUsage[key] || 0) + 1;
        }
      }
    }
  }

  // Procedure-specific validation
  if (resourceType === 'Procedure') {
    if (resource.status) {
      const key = `Procedure.status.${resource.status}`;
      stats.statusCodeUsage[key] = (stats.statusCodeUsage[key] || 0) + 1;
    }
  }

  // Patient-specific validation
  if (resourceType === 'Patient') {
    // Gender validation
    if (resource.gender) {
      const key = `Patient.gender.${resource.gender}`;
      stats.statusCodeUsage[key] = (stats.statusCodeUsage[key] || 0) + 1;

      const validGenders = ['male', 'female', 'other', 'unknown'];
      if (!validGenders.includes(resource.gender)) {
        outliers.push({
          patientId: resourceId,
          filename,
          resourceType,
          resourceId,
          outlierType: 'INVALID_PATIENT_GENDER',
          description: `Patient gender '${resource.gender}' is not a valid FHIR gender`,
          value: resource.gender,
          severity: 'medium'
        });
      }
    }
  }
}

async function validateResourceReferences(allResources: any[], filename: string, stats: StructuralStats, resourceIds: Set<string>) {
  const outliers = stats.outliers;

  for (const resource of allResources) {
    // Find all reference fields in the resource
    const references = findReferences(resource);

    for (const reference of references) {
      if (reference.reference) {
        stats.referenceCounts[reference.reference] = (stats.referenceCounts[reference.reference] || 0) + 1;

        // Validate internal references (urn:uuid:...)
        if (reference.reference.startsWith('urn:uuid:')) {
          const referencedId = reference.reference.replace('urn:uuid:', '');

          if (!resourceIds.has(referencedId)) {
            stats.brokenReferences++;
            outliers.push({
              patientId: resource.id,
              filename,
              resourceType: resource.resourceType,
              resourceId: resource.id,
              outlierType: 'BROKEN_INTERNAL_REFERENCE',
              description: `Resource references non-existent resource '${referencedId}'`,
              value: reference.reference,
              severity: 'high'
            });
          }
        }
      }
    }
  }
}

function findReferences(obj: any, references: any[] = []): any[] {
  if (obj && typeof obj === 'object') {
    if (Array.isArray(obj)) {
      for (const item of obj) {
        findReferences(item, references);
      }
    } else {
      for (const [key, value] of Object.entries(obj)) {
        if (key === 'reference' && typeof value === 'string') {
          references.push(obj);
        } else {
          findReferences(value, references);
        }
      }
    }
  }
  return references;
}

function reportStructuralFindings(stats: StructuralStats) {
  console.log('\n🏗️ FHIR STRUCTURE ANALYSIS RESULTS\n');
  console.log('=' .repeat(60));

  console.log(`Total bundles analyzed: ${stats.totalBundles}`);
  console.log(`Total resources analyzed: ${stats.totalResources}\n`);

  // Bundle transaction integrity
  console.log('📦 Bundle Transaction Integrity:');
  const integrity = stats.bundleTransactionIntegrity;
  console.log(`  Total entries: ${integrity.totalEntries}`);
  console.log(`  Entries with request: ${integrity.entriesWithRequest} (${(integrity.entriesWithRequest/integrity.totalEntries*100).toFixed(1)}%)`);
  console.log(`  Entries with fullUrl: ${integrity.entriesWithFullUrl} (${(integrity.entriesWithFullUrl/integrity.totalEntries*100).toFixed(1)}%)`);
  console.log(`  UUID mismatches: ${integrity.uuidMismatches}`);
  console.log('');

  // Resource type distribution
  console.log('📊 Resource Type Distribution:');
  Object.entries(stats.resourceCounts)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([type, count]) => {
      console.log(`  ${type}: ${count}`);
    });
  console.log('');

  // Coding system usage
  console.log('🏷️ Top Coding Systems:');
  Object.entries(stats.codingSystemUsage)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([system, count]) => {
      console.log(`  ${system}: ${count}`);
    });
  console.log('');

  // Status code distribution
  console.log('📊 Status Code Distribution:');
  Object.entries(stats.statusCodeUsage)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 15)
    .forEach(([status, count]) => {
      console.log(`  ${status}: ${count}`);
    });
  console.log('');

  // Extension usage
  console.log('🔧 Top Extensions:');
  Object.entries(stats.extensionUsage)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([extension, count]) => {
      console.log(`  ${extension}: ${count}`);
    });
  console.log('');

  // Reference integrity
  console.log('🔗 Reference Integrity:');
  console.log(`  Total references found: ${Object.values(stats.referenceCounts).reduce((sum, count) => sum + count, 0)}`);
  console.log(`  Broken references: ${stats.brokenReferences}`);
  console.log('');

  // Outliers by severity
  console.log('🚨 STRUCTURAL OUTLIERS DETECTED:\n');

  const severityGroups = {
    high: stats.outliers.filter(o => o.severity === 'high'),
    medium: stats.outliers.filter(o => o.severity === 'medium'),
    low: stats.outliers.filter(o => o.severity === 'low')
  };

  console.log(`❗ HIGH Severity: ${severityGroups.high.length}`);
  severityGroups.high.slice(0, 5).forEach(outlier => {
    console.log(`  🔥 ${outlier.outlierType}: ${outlier.description}`);
  });
  console.log('');

  console.log(`⚠️  MEDIUM Severity: ${severityGroups.medium.length}`);
  severityGroups.medium.slice(0, 5).forEach(outlier => {
    console.log(`  ⚠️  ${outlier.outlierType}: ${outlier.description}`);
  });
  console.log('');

  console.log(`ℹ️  LOW Severity: ${severityGroups.low.length}`);

  // Outlier type summary
  console.log('\n📈 STRUCTURAL OUTLIER TYPE SUMMARY:');
  const outlierTypes = [...new Set(stats.outliers.map(o => o.outlierType))];
  outlierTypes.forEach(type => {
    const count = stats.outliers.filter(o => o.outlierType === type).length;
    console.log(`  ${type}: ${count}`);
  });

  console.log('\n✅ FHIR structure analysis complete!');
}

if (import.meta.main) {
  main().catch(console.error);
}

